package io.github.miklires.mclans.gui;import io.github.miklires.mclans.MClansPlugin;import io.github.miklires.mclans.api.*;import io.github.miklires.mclans.clan.ClanService;import java.util.List;import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;
public final class ClanGui implements Listener{private final MClansPlugin plugin;private final ClanService service;public ClanGui(MClansPlugin plugin,ClanService service){this.plugin=plugin;this.service=service;}public void open(Player player,ClanView clan){service.repository().members(clan.id()).whenComplete((members,error)->plugin.scheduler().player(player,()->{if(error!=null){player.sendMessage(ClanService.color(service.text("&cCould not load the clan.","&cНе удалось загрузить клан.")));return;}ClanHolder holder=new ClanHolder();Inventory inv=Bukkit.createInventory(holder,54,ClanService.color("&e["+clan.tag()+"] "+clan.name()));holder.inventory(inv);inv.setItem(4,item(Material.BEACON,"&e"+clan.name(),List.of(service.text("&7Level: &f","&7Уровень: &f")+clan.level(),service.text("&7Points: &f","&7Очки: &f")+clan.points(),service.text("&7Members: &f","&7Участники: &f")+clan.memberCount(),service.text("&7Bank: &f","&7Банк: &f")+clan.bank(),service.text("&7Friendly fire: &f","&7Огонь по своим: &f")+clan.friendlyFire())));int slot=9;for(ClanMemberView m:members){if(slot>=54)break;inv.setItem(slot++,item(Material.PLAYER_HEAD,"&f"+m.playerName(),List.of(service.text("&7Role: &f","&7Роль: &f")+m.role())));}player.openInventory(inv);}));}@EventHandler public void click(InventoryClickEvent e){if(e.getInventory().getHolder(false) instanceof ClanHolder)e.setCancelled(true);}private static ItemStack item(Material material,String name,List<String> lore){ItemStack i=new ItemStack(material);ItemMeta m=i.getItemMeta();m.setDisplayName(ClanService.color(name));m.setLore(lore.stream().map(ClanService::color).toList());i.setItemMeta(m);return i;}}
